CREATE TABLE IF NOT EXISTS Marketing.Campaigns
(
 CampaignID  integer NOT NULL AUTOINCREMENT COMMENT 'A unique identifier for each campaign in the table. This primary key ensures that each campaign record is distinct and can be referenced individually.',
 Name        varchar(16777216) COMMENT 'The name of the campaign. This field provides a concise, descriptive label for the campaign, making it easy to identify and refer to in reports, dashboards, and other analyses.',
 Description varchar(16777216) COMMENT 'A detailed description of the campaign, including its goals, target audience, strategies, and key activities. This field helps provide context and understanding of the campaign’s purpose and scope.',
