 Status      varchar(16777216) COMMENT 'The current status of the campaign, such as "Planned," "Active," "Completed," or "Cancelled." This field helps track the progress of the campaign and supports decision-making regarding ongoing and future marketing activities.',

 CONSTRAINT PK_Campaigns PRIMARY KEY ( CampaignID )
)
COMMENT = 'The Campaigns table stores information about marketing or sales campaigns conducted by the organization. This table captures details about each campaign, including its objectives, duration, and current status. It is essential for tracking and managing marketing activities, analyzing campaign effectiveness, and linking campaigns to sales orders and customer interactions.';
